def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    en = [(props.get(t.get('element')) or {}).get('eneg') for t in sites]
    weight = 0.0
    first = 0.0
    for i in range(n):
        if en[i] is not None:
            weight += occ[i]
            first += occ[i] * en[i]
    if weight <= 0:
        return 0.0
    mean = first / weight
    variance = 0.0
    for i in range(n):
        if en[i] is not None:
            variance += occ[i] * (en[i] - mean) ** 2 / weight
    if variance <= 0.000000000001:
        return 0.0
    contrast = 0.0
    contacts = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0:
            a = radii[i]
            b = radii[j]
            ei = en[i]
            ej = en[j]
            if a is not None and b is not None and a > 0 and b > 0 and ei is not None and ej is not None:
                x = d / (1.2 * (a + b))
                w = occ[i] * occ[j] / (1.0 + x ** 12)
                contacts += w
                contrast += w * (ei - ej) ** 2
    if contacts <= 0:
        return 0.0
    return contrast / (contacts * 2.0 * variance)

